create table "web_game" ("id" bigint primary key, "name" varchar(128) not null, "slug" varchar(160) not null, "genre" varchar(64) not null, "thumb_key" varchar(64) not null, "creator" varchar(64) not null default 'EconomySim Games', "tagline" varchar(256) not null default '', "description" text not null default '', "instructions" text not null default '', "plays" bigint not null default '0', "likes" bigint not null default '0', "dislikes" bigint not null default '0', "created_at" timestamptz not null default CURRENT_TIMESTAMP);
create index "web_game_genre_index" on "web_game" ("genre");
