INSERT INTO "web_game" ("id", "name", "slug", "genre", "thumb_key", "creator", "tagline", "description", "instructions") VALUES (101, 'Sky Obby: Tower Trials', 'Sky-Obby-Tower-Trials', 'Adventure', 'skyObby', 'EconomySim Games', 'Climb the floating towers. Do not look down.', 'Welcome to Sky Obby: Tower Trials! Jump your way up an endless tower of floating platforms, vanishing bricks and moving danger. Grab coins for bonus points, reach the checkpoint flags, and see how high you can climb before you run out of lives. Beat your friends on the leaderboard!', 'Move with the arrow keys or A/D. Jump with Space, W or Up arrow. You can also tap the left/right side of the game to move and tap the top to jump. Land on platforms, collect coins, avoid falling. 3 lives per run.');
INSERT INTO "web_game" ("id", "name", "slug", "genre", "thumb_key", "creator", "tagline", "description", "instructions") VALUES (102, 'Brick Busters', 'Brick-Busters', 'Arcade', 'brickBusters', 'EconomySim Games', 'Smash every brick. Classic arcade, 2016 style.', 'The classic brick-busting arcade game, rebuilt for the web client! Keep the ball in play, clear every colorful brick, and climb through the levels as the ball gets faster. Catch the wide-paddle power-up, and try to set a high score!', 'Move the paddle with your mouse, arrow keys or A/D. Click or press Space to launch the ball. Break every brick to advance a level. You have 3 lives - do not let the ball past the paddle!');
INSERT INTO "web_game" ("id", "name", "slug", "genre", "thumb_key", "creator", "tagline", "description", "instructions") VALUES (103, 'Crossy Canyon', 'Crossy-Canyon', 'Classic', 'crossyCanyon', 'EconomySim Games', 'Cross the canyon. Dodge traffic. Ride the logs.', 'How far can you get? Hop across the busy canyon road, dodge speeding cars and trucks, then ride the floating logs across the river. Every row you cross scores a point - but one wrong hop and it is back to the start!', 'Use the arrow keys or WASD to hop one tile at a time (tap or swipe on touch screens). Get run over by a car or fall in the river and you lose. Score 1 point per row crossed - keep going for a new record!');
INSERT INTO "web_catalog_item" ("id", "name", "description", "category", "price", "currency", "art") VALUES (1001, 'Red Baseball Cap', 'A classic red cap. Perfect for sunny days in Robloxia.', 'hats', 35, 'tix', '{"type":"hat","shape":"cap","colors":{"main":"#d62d20","accent":"#ffffff"}}');
